function coinChange(coins, amount) {
  const memo = {};
  function dfs(rem) {
    if (rem === 0) return 0;
    if (rem < 0) return Infinity;
    if (rem in memo) return memo[rem];
    let best = Infinity;
    for (const c of coins) best = Math.min(best, 1 + dfs(rem - c));
    memo[rem] = best;
    return best;
  }
  const r = dfs(amount);
  return r === Infinity ? -1 : r;
}
